from pathlib import Path
from html.parser import HTMLParser
out=Path('/app/output')
files=list(out.glob('*.html'))
class P(HTMLParser):
 def __init__(self): super().__init__(); self.hrefs=[]; self.ids=[]; self.buttons=0
 def handle_starttag(self,tag,attrs):
  d=dict(attrs)
  if 'href' in d: self.hrefs.append(d['href'])
  if 'id' in d: self.ids.append(d['id'])
  if tag=='button': self.buttons+=1
all_ids={f.name:set() for f in files}
parsers={}
for f in files:
 p=P(); p.feed(f.read_text()); parsers[f.name]=p; all_ids[f.name]=set(p.ids)
missing=[]
for f,p in parsers.items():
 for href in p.hrefs:
  if href.startswith(('http','#mailto:','tel:')) or href == '#': continue
  path,_,frag=href.partition('#')
  target=(out/path) if path else f
  if path and not target.exists(): missing.append((f,href,'file'))
  elif frag and frag not in all_ids[target.name]: missing.append((f,href,'anchor'))
print('html files', [f.name for f in files])
print('missing', missing)
for term in ['Invest, Finance & Value','Plan, Lease & Occupy','Design & Build','Manage Properties & Portfolios','Transform Business Outcomes','Invest in Real Assets','Project & Program Management','Supply Chain Sourcing']:
 found=any(term in f.read_text() for f in files)
 print(term, found)
print('css size', (out/'styles.css').stat().st_size, 'js size', (out/'script.js').stat().st_size)
